const savedTheme=localStorage.getItem("theme"),systemPrefersDark=window.matchMedia("(prefers-color-scheme: dark)").matches,theme=savedTheme?savedTheme:systemPrefersDark?"dark":"light";document.documentElement.setAttribute("data-theme",theme),document.addEventListener("DOMContentLoaded",()=>{const e=document.documentElement;document.getElementById("theme-toggle").addEventListener("click",()=>{const t=e.getAttribute("data-theme")==="dark"?"light":"dark";e.setAttribute("data-theme",t),localStorage.setItem("theme",t)})})